    return {"routes": routes, "metadata": {"seed": seed, "total_distance": calculate_total_distance(instance, routes)}}

def calculate_total_distance(instance, routes):
    total_distance = 0
    for route in routes:
        for i in range(len(route) - 1):
            total_distance += distance(instance.node_map[route[i]], instance.node_map[route[i + 1]])
    return total_distance

def is_battery_feasible(instance, route):
    states = propagate_route(instance, route)
    return all(state.battery_arrival >= 0 for state in states)

def solve(instance, seed: int, time_limit_s: float):
    depot = instance.depot_id
    routes = []
    visited_customers = set()

    for cid in instance.customer_ids:
        if cid in visited_customers:
            continue
        route = [depot, cid, depot]

        if is_battery_feasible(instance, route):
            routes.append(route)
            visited_customers.add(cid)
            continue

        for station_id in instance.station_ids:
            for i in range(1, len(route)):
                new_route = route[:i] + [station_id] + route[i:]
                if is_battery_feasible(instance, new_route):
                    routes.append(new_route)
                    visited_customers.add(cid)
                    break
            else:
                continue
            break

    # Sort routes by length to minimize total distance
    routes.sort(key=len)

    return {"routes": routes, "metadata": {"seed": seed, "vehicles_sum": len(routes), "distance_sum": calculate_total_distance(instance, routes)}}
